from __future__ import annotations

from dataclasses import dataclass
from decimal import ROUND_HALF_UP, Decimal


@dataclass(frozen=True)
class Coupon:
    code: str
    percent_off: Decimal
    active: bool


class PricingService:
    def __init__(self, coupons: dict[str, Coupon]):
        self._coupons = coupons

    def final_price(self, subtotal: Decimal, coupon_code: str | None) -> Decimal:
        """Apply the coupon if it exists and is active; unknown or inactive codes are ignored."""
        if not coupon_code:
            return subtotal
        coupon = self._coupons.get(coupon_code.strip().upper())
        if not coupon.active:
            return subtotal
        discount = subtotal * coupon.percent_off / Decimal(100)
        return (subtotal - discount).quantize(Decimal("0.01"), rounding=ROUND_HALF_UP)

from __future__ import annotations

from dataclasses import dataclass
from decimal import ROUND_HALF_UP, Decimal


@dataclass(frozen=True)
class Coupon:
    code: str
    percent_off: Decimal
    active: bool


class PricingService:
    def __init__(self, coupons: dict[str, Coupon]):
        self._coupons = coupons

    def final_price(self, subtotal: Decimal, coupon_code: str | None) -> Decimal:
        """Apply the coupon if it exists and is active; unknown or inactive codes are ignored."""
        if not coupon_code:
            return subtotal
        coupon = self._coupons.get(coupon_code.strip().upper())
        if coupon is None or not coupon.active:
            return subtotal
        discount = subtotal * coupon.percent_off / Decimal(100)
        return (subtotal - discount).quantize(Decimal("0.01"), rounding=ROUND_HALF_UP)

from dataclasses import dataclass


@dataclass(frozen=True)
class Share:
    member_id: str
    amount_cents: int


def split_bill(total_cents: int, member_ids: list[str]) -> list[Share]:
    """Split a bill evenly between members.

    Amounts are whole cents and must add up exactly to total_cents; when the
    total does not divide evenly, the first members pay one extra cent each.
    """
    if not member_ids:
        raise ValueError("at least one member is required")
    if total_cents < 0:
        raise ValueError("total must not be negative")
    base = total_cents // len(member_ids)
    return [Share(member_id, base) for member_id in member_ids]

from dataclasses import dataclass


@dataclass(frozen=True)
class Share:
    member_id: str
    amount_cents: int


def split_bill(total_cents: int, member_ids: list[str]) -> list[Share]:
    """Split a bill evenly between members.

    Amounts are whole cents and must add up exactly to total_cents; when the
    total does not divide evenly, the first members pay one extra cent each.
    """
    if not member_ids:
        raise ValueError("at least one member is required")
    if total_cents < 0:
        raise ValueError("total must not be negative")
    base, remainder = divmod(total_cents, len(member_ids))
    return [Share(member_id, base + (1 if index < remainder else 0)) for index, member_id in enumerate(member_ids)]
